import { readFileSync } from "node:fs";

import type { APIRequestContext } from "@playwright/test";

import { expect, sample, test, uniqueName } from "../../fixtures";

type VendorOut = { id: string; name: string; status: string };
type VendorPageOut = { items: VendorOut[]; total: number; limit: number; offset: number };
type DocumentOut = { id: string; status: string };
type ExtractionOut = { id: string };

const DOCS = [
  ["w9", "w9.txt"],
  ["insurance_certificate", "insurance_certificate.txt"],
  ["contract", "contract.txt"],
] as const;

function contactEmail(): string {
  return `vendor.${Math.random().toString(36).slice(2, 10)}@example.com`;
}

async function createVendor(member: APIRequestContext, name: string): Promise<VendorOut> {
  const res = await member.post("/api/vendors", {
    data: { name, category: "logistics", contact_email: contactEmail() },
  });
  expect(res.status(), await res.text()).toBe(201);
  return (await res.json()) as VendorOut;
}

async function approvedVendor(
  member: APIRequestContext,
  reviewer: APIRequestContext,
  name: string,
): Promise<VendorOut> {
  const vendor = await createVendor(member, name);

  const documents: DocumentOut[] = [];
  for (const [kind, file] of DOCS) {
    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind,
        file: { name: file, mimeType: "text/plain", buffer: readFileSync(sample(file)) },
      },
    });
    expect(res.status(), await res.text()).toBe(201);
    documents.push((await res.json()) as DocumentOut);
  }

  for (const doc of documents) {
    await expect
      .poll(
        async () => {
          const res = await member.get(`/api/documents/${doc.id}`);
          return ((await res.json()) as DocumentOut).status;
        },
        { timeout: 60_000 },
      )
      .toBe("extracted");
  }

  const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submitted.status(), await submitted.text()).toBe(200);

  for (const doc of documents) {
    const extractionRes = await reviewer.get(`/api/documents/${doc.id}/extraction`);
    expect(extractionRes.status(), await extractionRes.text()).toBe(200);
    const extraction = (await extractionRes.json()) as ExtractionOut;
    const decided = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
      data: { decision: "approve" },
    });
    expect(decided.status(), await decided.text()).toBe(200);
  }

  return vendor;
}

test("lists vendors with status filter, pagination, and search", { tag: "@VEN-05" }, async ({ apiAs }) => {
  test.setTimeout(180_000);

  // Arrange: 25 vendors in the member's tenant, 5 of them approved.
  // Every vendor carries a unique marker so list calls can be scoped to this test's data,
  // since other tests share the tenant and database and run in parallel.
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const marker = uniqueName("Lst");

  await Promise.all(
    Array.from({ length: 5 }, (_, i) => approvedVendor(member, reviewer, `${marker} Approved ${i}`)),
  );
  await Promise.all(
    Array.from({ length: 20 }, (_, i) =>
      createVendor(member, i === 0 ? `${marker} Freight Co` : `${marker} Draft Supply ${i}`),
    ),
  );

  // Act + Assert: status filter.
  const approvedRes = await member.get("/api/vendors", { params: { q: marker, status: "approved" } });
  expect(approvedRes.status(), await approvedRes.text()).toBe(200);
  const approved = (await approvedRes.json()) as VendorPageOut;
  expect(approved.items).toHaveLength(5);
  expect(approved.total).toBe(5);
  for (const vendor of approved.items) {
    expect(vendor.status).toBe("approved");
  }

  // Act + Assert: pagination.
  const pageRes = await member.get("/api/vendors", { params: { q: marker, limit: 10, offset: 20 } });
  expect(pageRes.status(), await pageRes.text()).toBe(200);
  const page = (await pageRes.json()) as VendorPageOut;
  expect(page.items).toHaveLength(5);
  expect(page.total).toBe(25);

  // Act + Assert: search is case-insensitive over vendor names.
  const searchRes = await member.get("/api/vendors", { params: { q: "freight", limit: 100 } });
  expect(searchRes.status(), await searchRes.text()).toBe(200);
  const search = (await searchRes.json()) as VendorPageOut;
  expect(search.items.length).toBeGreaterThan(0);
  for (const vendor of search.items) {
    expect(vendor.name.toLowerCase()).toContain("freight");
  }
});
